// Generated by scripts/prepare-telegram-bot.mjs; contains no credentials.
export const telegramSources: Record<string,string> = {
  "schema": "import {table,text,integer} from 'sdk/db';\nexport const settings=table('settings',{key:text('key').primaryKey(),value:text('value').notNull()});\nexport const users=table('users',{telegramId:integer('telegram_id').primaryKey(),authorId:text('author_id').notNull(),updatedAt:integer('updated_at').notNull()});\n",
  "handlers/message": "import {api,db} from 'sdk';\nimport {bridge} from '../lib/bridge.js';\nimport {showMenu,showArticles,appUrl} from '../lib/menu.js';\nexport default async function(message){\n if(message.chat?.type!=='private'||!message.from||message.from.is_bot)return;\n const text=(message.text||'').trim(),telegramId=message.from.id;\n try{\n  const account=await bridge({action:'start',telegramId});\n  await db.run('INSERT INTO users (telegram_id,author_id,updated_at) VALUES (:tg,:author,:now) ON CONFLICT(telegram_id) DO UPDATE SET author_id=excluded.author_id,updated_at=excluded.updated_at',{':tg':telegramId,':author':account.authorId,':now':Date.now()});\n  if(/^\\/articles(?:@\\w+)?(?:\\s|$)/.test(text)){await showArticles(message.chat.id,telegramId);return;}\n  if(/^\\/delete(?:@\\w+)?(?:\\s|$)/.test(text)){await showArticles(message.chat.id,telegramId,'delete');return;}\n  if(/^\\/new(?:@\\w+)?(?:\\s|$)/.test(text)){await api.sendMessage({chat_id:message.chat.id,text:'Откройте редактор. Черновик и публикация будут принадлежать вам в Telegram.',reply_markup:{inline_keyboard:[[{text:'Начать новую статью',web_app:{url:appUrl('new')}}]]}});return;}\n  await showMenu(message.chat.id);\n }catch(error){await api.sendMessage({chat_id:message.chat.id,text:error instanceof Error?error.message:'Не удалось открыть статьи. Попробуйте ещё раз.'});}\n}\n",
  "handlers/callback_query": "import {api} from 'sdk';\nimport {bridge} from '../lib/bridge.js';\nimport {showMenu,showArticles} from '../lib/menu.js';\nexport default async function(query){\n if(query.message?.chat?.type!=='private'||!query.from||query.from.is_bot)return;\n await api.answerCallbackQuery({callback_query_id:query.id});\n const chatId=query.message.chat.id,telegramId=query.from.id,data=query.data||'';\n try{\n  if(data==='menu'){await showMenu(chatId);return;}\n  const list=/^(articles|delete):(\\d{1,3})$/.exec(data);\n  if(list){await showArticles(chatId,telegramId,list[1],Number(list[2]));return;}\n  const remove=/^remove:([a-f0-9-]{36})$/.exec(data);\n  if(remove){const result=await bridge({action:'article',telegramId,articleId:remove[1]}),article=result.article;await api.sendMessage({chat_id:chatId,text:'Удалить «'+article.title.slice(0,200)+'»? Статья и все её адреса перестанут открываться.',reply_markup:{inline_keyboard:[[{text:'Да, удалить',callback_data:'confirm:'+article.id+':'+article.version}],[{text:'Отмена',callback_data:'delete:0'}]]}});return;}\n  const confirm=/^confirm:([a-f0-9-]{36}):(\\d{1,10})$/.exec(data);\n  if(confirm){await bridge({action:'delete',telegramId,articleId:confirm[1],version:Number(confirm[2])});await api.sendMessage({chat_id:chatId,text:'Статья удалена.'});await showArticles(chatId,telegramId,'delete');return;}\n  await showMenu(chatId);\n }catch(error){await api.sendMessage({chat_id:chatId,text:error instanceof Error?error.message:'Не удалось выполнить действие. Обновите список.'});}\n}\n",
  "lib/bridge": "import {db,fetch} from 'sdk';\nexport const SITE='https://list.vitaledanilov.workers.dev';\nexport async function bridge(input){const config=await db.get('SELECT value FROM settings WHERE key=:key',{':key':'bridge_secret'});if(!config)throw new Error('Бот ещё не настроен владельцем.');const response=await fetch(SITE+'/api/telegram/bridge',{method:'POST',headers:{'Content-Type':'application/json','User-Agent':'List-Telegram-Serverless/1.0','X-List-Bridge':config.value},body:JSON.stringify(input)});const data=await response.json();if(!response.ok)throw new Error(data.error||'Сайт временно недоступен.');return data;}\n",
  "lib/setup": "// Executed only by the authenticated management API; never a public endpoint.\nimport {api,db,fetch} from 'sdk';\nimport {SITE} from './bridge.js';\nimport {appUrl} from './menu.js';\nexport default async function(input){\n if(typeof input?.bridgeSecret!=='string'||input.bridgeSecret.length<32)throw new Error('A bridge secret is required');\n const me=await api.getMe({});\n const response=await fetch(SITE+'/api/telegram/bridge',{method:'POST',headers:{'Content-Type':'application/json','User-Agent':'List-Telegram-Serverless/1.0','X-List-Bridge':input.bridgeSecret},body:JSON.stringify({action:'configure',username:me.username,botId:me.id})});\n if(!response.ok)throw new Error('Website setup failed');\n await db.run('INSERT INTO settings (key,value) VALUES (:key,:value) ON CONFLICT(key) DO UPDATE SET value=excluded.value',{':key':'bridge_secret',':value':input.bridgeSecret});\n try{await api.setChatMenuButton({menu_button:{type:'web_app',text:'Мои статьи',web_app:{url:appUrl('articles')}}});await api.setMyCommands({commands:[{command:'start',description:'Открыть меню'},{command:'articles',description:'Мои статьи и черновики'},{command:'new',description:'Начать новую статью'},{command:'delete',description:'Удалить свою статью'}]});}catch{}\n return {ready:true,username:me.username};\n}\n",
  "lib/menu": "import {api} from 'sdk';\nimport {bridge,SITE} from './bridge.js';\nexport function appUrl(screen='articles',article){return SITE+'/_list/app?screen='+encodeURIComponent(screen)+(article?'&article='+encodeURIComponent(article):'');}\nexport const menu={inline_keyboard:[[{text:'Мои статьи',callback_data:'articles:0'}],[{text:'Новая статья',web_app:{url:appUrl('new')}}],[{text:'Удалить статью',callback_data:'delete:0'}]]};\nexport async function showMenu(chatId){await api.sendMessage({chat_id:chatId,text:'Лист — ваши статьи. Пишите, возвращайтесь к черновикам и редактируйте публикации. Доступ в Telegram определяется автоматически.',reply_markup:menu});}\nexport async function showArticles(chatId,telegramId,mode='articles',page=0){\n const data=await bridge({action:'articles',telegramId}),all=data.articles||[],start=Math.max(0,Math.min(Number(page)||0,Math.max(0,Math.ceil(all.length/8)-1)))*8;\n const rows=[];\n for(const article of all.slice(start,start+8)){\n  const label=(article.published?'✓ ':'✎ ')+(article.title||'Без названия').slice(0,44);\n  if(mode==='delete')rows.push([{text:label,callback_data:'remove:'+article.id}]);\n  else {rows.push([{text:label,web_app:{url:appUrl('edit',article.id)}}]);if(article.published)rows.push([{text:'Предпросмотр',web_app:{url:appUrl('read',article.id)}}]);}\n }\n const paging=[];if(start>0)paging.push({text:'← Назад',callback_data:mode+':'+(start/8-1)});if(start+8<all.length)paging.push({text:'Далее →',callback_data:mode+':'+(start/8+1)});if(paging.length)rows.push(paging);\n rows.push([{text:'Новая статья',web_app:{url:appUrl('new')}},{text:'Меню',callback_data:'menu'}]);\n await api.sendMessage({chat_id:chatId,text:all.length?(mode==='delete'?'Выберите статью для удаления. Перед удалением будет подтверждение.':'Ваши статьи: ✓ опубликовано, ✎ черновик. Нажмите название, чтобы редактировать.'):'Статей пока нет. Создайте первую — черновик будет сохраняться автоматически.',reply_markup:{inline_keyboard:rows}});\n}\n"
};
